import {recipes, ingredients, matchRecipe, filterRecipes, totalTime} from './recipes.js';
const $=s=>document.querySelector(s);
const read=(key,fallback)=>{try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback;}catch{return fallback;}};
const state={pantry:read('pp-pantry',[]).filter(i=>ingredients.includes(i)),equipment:read('pp-equipment',[]).filter(e=>['Stovetop','Oven','Air fryer','Microwave'].includes(e)),saved:read('pp-saved',[]),time:9999,calories:9999,category:'All recipes',sort:'relevant',query:'',onlyHave:false,page:'discover'};
const icons={clock:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',fire:'<svg viewBox="0 0 24 24"><path d="M13 3c1 6 7 7 7 12a8 8 0 0 1-16 0c0-3 2-5 4-7 0 3 2 4 3 4 2-2 2-5 2-9Z"/></svg>',bookmark:'<svg viewBox="0 0 24 24"><path d="M6 3h12v18l-6-4-6 4Z"/></svg>'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoStyle=i=>`--photo-x:${(i%3)*50}%;--photo-y:${Math.floor(i/3)*100/3}%`;
const duration=r=>totalTime(r)>=60?`${Math.floor(totalTime(r)/60)}h ${totalTime(r)%60||''}${totalTime(r)%60?'m':''}`:`${totalTime(r)} min`;
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Storage is unavailable. Your changes will last for this visit.');}}
function renderPantry(){
 $('#pantry').innerHTML=state.pantry.map(i=>`<button class="chip selected" data-remove="${esc(i)}" aria-label="Remove ${esc(i)}">${esc(i)} <span aria-hidden="true">×</span></button>`).join('');
 $('#pantry-hint').hidden=state.pantry.length>0;
 $('#popular').innerHTML=['Chicken','Rice','Eggs','Tomato','Garlic','Spinach','Pasta','Chickpeas'].filter(i=>!state.pantry.includes(i)).map(i=>`<button class="chip" data-add="${i}">${i} <span aria-hidden="true">+</span></button>`).join('');
 $('#equipment').innerHTML=['Stovetop','Oven','Air fryer','Microwave'].map(e=>`<button class="chip ${state.equipment.includes(e)?'selected':''}" data-equipment="${e}" aria-pressed="${state.equipment.includes(e)}">${e}</button>`).join('');
}
function render(){
 renderPantry();
 const saved=state.page==='saved';
 $('#results-title').textContent=saved?'Your own little cookbook':state.pantry.length?'Good things from your kitchen':'A little inspiration for today';
 $('#results-subtitle').textContent=saved?'The recipes you’ll want to come back to.':state.pantry.length?'Sorted by the ingredients you already have.':'Good meals start with what you have on hand.';
 $('#saved-count').textContent=state.saved.length?state.saved.length:'';
 document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.setAttribute('aria-pressed',String(b.dataset.page===state.page));});
 $('.categories').innerHTML=['All recipes','Quick & easy','Vegetarian','High protein'].map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('');
 const list=filterRecipes(saved?recipes.filter(r=>state.saved.includes(r.id)):recipes,state);
 $('#result-count').textContent=`${list.length} ${list.length===1?'recipe':'recipes'}${state.pantry.length?' matched':''}`;
 $('#recipe-grid').innerHTML=list.length?list.map(r=>{const m=matchRecipe(r,state.pantry);const isSaved=state.saved.includes(r.id);return `<article class="recipe-card"><div class="card-image"><button class="photo-button" data-recipe="${r.id}" aria-label="View ${r.title}"><span class="food-photo" style="${photoStyle(r.image)}" role="img" aria-label="${r.title}"></span></button><button class="icon-button bookmark ${isSaved?'saved':''}" data-save="${r.id}" aria-label="${isSaved?'Unsave':'Save'} ${r.title}" aria-pressed="${isSaved}">${icons.bookmark}</button></div><div class="card-content"><button class="recipe-title" data-recipe="${r.id}">${r.title}</button><div class="recipe-meta"><span>${icons.clock}${duration(r)}</span><i></i><span>${icons.fire}${r.kcal} kcal</span></div><p class="match">${state.pantry.length?m.missing.length?`<strong>${m.have} of ${m.total}</strong> ingredients in your kitchen`:'<strong>Everything you need is in your kitchen</strong>':r.category==='Vegetarian'?'Vegetarian · Full of the good stuff':'High protein · Satisfying & simple'}</p></div></article>`;}).join(''):`<div class="empty"><span class="empty-symbol" aria-hidden="true">♧</span><h3>${saved&&!state.saved.length?'Your cookbook starts here':'No recipes just yet'}</h3><p>${saved&&!state.saved.length?'Tap the bookmark on a recipe to keep it here.':'Try a little more time, another ingredient, or fewer filters.'}</p><button class="primary" id="empty-reset">${saved&&!state.saved.length?'Explore recipes':'Clear filters'}</button></div>`;
}
function addIngredient(i){if(!ingredients.includes(i)||state.pantry.includes(i))return;state.pantry.push(i);persist('pp-pantry',state.pantry);$('#ingredient-search').value='';$('#suggestions').hidden=true;$('#ingredient-search').setAttribute('aria-expanded','false');render();}
function suggestions(){const q=$('#ingredient-search').value.trim().toLowerCase();const matches=ingredients.filter(i=>!state.pantry.includes(i)&&i.toLowerCase().includes(q));$('#suggestions').hidden=!q;$('#ingredient-search').setAttribute('aria-expanded',String(!!q));$('#suggestions').innerHTML=matches.length?matches.slice(0,8).map(i=>`<button data-add="${esc(i)}">${esc(i)} <span>+</span></button>`).join(''):'<p>No matching ingredient in this collection.</p>';}
function reset(){Object.assign(state,{pantry:[],equipment:[],time:9999,calories:9999,category:'All recipes',sort:'relevant',query:'',onlyHave:false});persist('pp-pantry',[]);persist('pp-equipment',[]);$('#time').value='9999';$('#calories').value='9999';$('#sort').value='relevant';$('#only-have').checked=false;$('#recipe-search').value='';$('#ingredient-search').value='';$('#suggestions').hidden=true;$('#ingredient-search').setAttribute('aria-expanded','false');render();}
function save(id){state.saved=state.saved.includes(id)?state.saved.filter(s=>s!==id):[...state.saved,id];persist('pp-saved',state.saved);render();if(activeRecipe)renderDetail();toast(state.saved.includes(id)?'Recipe added to your cookbook':'Recipe removed from your cookbook');}
let activeRecipe=null,servings=1,completed=new Set(),checked=new Set(),returnFocus=null;
function quantity(n){return Number.isInteger(n)?n:Number(n.toFixed(2));}
function renderDetail(){const r=activeRecipe;const m=matchRecipe(r,state.pantry);$('#recipe-detail').innerHTML=`<div class="detail-photo food-photo" style="${photoStyle(r.image)}" role="img" aria-label="${r.title}"></div><div class="detail-body"><p class="detail-category">${r.category} · ${r.equipment.length?r.equipment.join(' + '):'No cooking equipment needed'}</p><h2 id="detail-title">${r.title}</h2><p class="detail-description">${r.description}</p><div class="detail-stats"><span><strong>${r.prep} min</strong>Prep</span><span><strong>${r.cook} min</strong>Cook</span>${r.wait?`<span><strong>${r.wait/60} hours</strong>Chill</span>`:''}<span><strong>${r.kcal} kcal</strong>Per serving</span><span><strong>${r.protein} g</strong>Protein</span></div><div class="detail-actions"><div class="servings"><span>Servings</span><button data-servings="-1" aria-label="Fewer servings" ${servings===1?'disabled':''}>−</button><output>${servings}</output><button data-servings="1" aria-label="More servings" ${servings===8?'disabled':''}>+</button></div><button class="secondary" data-save="${r.id}">${state.saved.includes(r.id)?'Saved to cookbook':'Save recipe'}</button></div><div class="detail-columns"><section><h3>What you’ll need</h3><p class="hint">${m.have} of ${m.total} main ingredients in your kitchen</p><ul class="ingredient-list">${r.ingredients.map(([name,n,unit],i)=>`<li><label><input type="checkbox" data-check="${i}" ${checked.has(i)?'checked':''}><span>${quantity(n*servings)} ${unit} <strong>${name.toLowerCase()}</strong>${state.pantry.includes(name)?'<small>In your kitchen</small>':''}</span></label></li>`).join('')}</ul><p class="hint">Plus salt, pepper and water as needed. Oil is treated as a pantry basic.</p></section><section><h3>Let’s make it</h3><p class="hint" id="step-progress">${completed.size} of ${r.steps.length} steps complete</p><ol class="steps">${r.steps.map(([title,text],i)=>`<li class="${completed.has(i)?'done':''}"><button class="step-number" data-step="${i}" aria-label="${completed.has(i)?'Mark incomplete':'Complete'}: ${esc(title)}" aria-pressed="${completed.has(i)}">${completed.has(i)?'✓':i+1}</button><div><h4>${title}</h4><p>${text}</p></div></li>`).join('')}</ol></section></div><div class="video-reference"><div><h3>Prefer to watch?</h3><p>Explore video tutorials for this dish on YouTube.</p></div><a class="secondary" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query=${encodeURIComponent(r.title+' recipe tutorial')}">Find video tutorials ↗</a></div><p class="nutrition-note">Nutrition values are estimates per serving and will vary with brands and portions. Check ingredient labels for allergens. Photos are illustrative.</p></div>`;}
function openRecipe(id){activeRecipe=recipes.find(r=>r.id===id);if(!activeRecipe)return;returnFocus=document.activeElement;servings=1;completed=new Set();checked=new Set();renderDetail();$('#recipe-dialog').showModal();$('#recipe-dialog').scrollTop=0;document.body.classList.add('modal-open');$('#close-dialog').focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.add)addIngredient(d.add);if(d.remove){state.pantry=state.pantry.filter(i=>i!==d.remove);persist('pp-pantry',state.pantry);render();}if(d.equipment){state.equipment=state.equipment.includes(d.equipment)?state.equipment.filter(i=>i!==d.equipment):[...state.equipment,d.equipment];persist('pp-equipment',state.equipment);render();}if(d.category){state.category=d.category;render();}if(d.page){state.page=d.page;render();if(d.page==='saved')$('.results').scrollIntoView({behavior:'smooth',block:'start'});}if(d.recipe)openRecipe(d.recipe);if(d.save)save(d.save);if(d.servings){servings=Math.max(1,Math.min(8,servings+Number(d.servings)));renderDetail();}if(d.step!==undefined){const i=Number(d.step);completed.has(i)?completed.delete(i):completed.add(i);renderDetail();if(completed.size===activeRecipe.steps.length)toast('All done. Enjoy your meal!');}if(b.id==='empty-reset'){reset();state.page='discover';render();}});
$('#recipe-dialog').addEventListener('change',e=>{if(e.target.dataset.check!==undefined){const i=Number(e.target.dataset.check);e.target.checked?checked.add(i):checked.delete(i);}});
$('#close-dialog').onclick=()=>$('#recipe-dialog').close();$('#recipe-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');activeRecipe=null;if(returnFocus?.isConnected)returnFocus.focus();});$('#recipe-dialog').addEventListener('click',e=>{if(e.target===$('#recipe-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#ingredient-search').addEventListener('input',suggestions);$('#ingredient-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const b=$('#suggestions button');if(b)addIngredient(b.dataset.add);}if(e.key==='Escape'){$('#suggestions').hidden=true;$('#ingredient-search').setAttribute('aria-expanded','false');}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-field')&&!e.target.closest('#suggestions')){$('#suggestions').hidden=true;$('#ingredient-search').setAttribute('aria-expanded','false');}});
for(const id of ['time','calories','sort'])$('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render();});$('#only-have').addEventListener('change',e=>{state.onlyHave=e.target.checked;render();});$('#recipe-search').addEventListener('input',e=>{state.query=e.target.value;render();});$('#reset').onclick=reset;$('#find').onclick=()=>{render();$('.results').scrollIntoView({behavior:'smooth',block:'start'});toast($('#result-count').textContent);};
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
